def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [v for v in set(v for row in grid for v in row) if v != bg]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    out = [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and out[r][c] == bg:
                out[r][c] = 2
    # Join marker pixels horizontally; untouched cells outside such spans remain unchanged.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if out[r][c] == bg:
                        out[r][c] = 2
    return out

